// LoadPorTitulos allows an eager lookup of values, cached into the
// loaded structs of the objects. This is for a 1-M or N-M relationship.
func (portadorL) LoadPorTitulos(ctx context.Context, e boil.ContextExecutor, singular bool, maybePortador interface{}, mods queries.Applicator) error {
	var slice []*Portador
	var object *Portador

	if singular {
		var ok bool
		object, ok = maybePortador.(*Portador)
		if !ok {
			object = new(Portador)
			ok = queries.SetFromEmbeddedStruct(&object, &maybePortador)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", object, maybePortador))
			}
		}
	} else {
		s, ok := maybePortador.(*[]*Portador)
		if ok {
			slice = *s
		} else {
			ok = queries.SetFromEmbeddedStruct(&slice, maybePortador)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", slice, maybePortador))
			}
		}
	}

	args := make(map[interface{}]struct{})
	if singular {
		if object.R == nil {
			object.R = &portadorR{}
		}
		args[object.PorID] = struct{}{}
	} else {
		for _, obj := range slice {
			if obj.R == nil {
				obj.R = &portadorR{}
			}
			args[obj.PorID] = struct{}{}
		}
	}

	if len(args) == 0 {
		return nil
	}

	argsSlice := make([]interface{}, len(args))
	i := 0
	for arg := range args {
		argsSlice[i] = arg
		i++
	}

	query := NewQuery(
		qm.From(`titulos`),
		qm.WhereIn(`titulos.por_id in ?`, argsSlice...),
	)
	if mods != nil {
		mods.Apply(query)
	}

	results, err := query.QueryContext(ctx, e)
	if err != nil {
		return errors.Wrap(err, "failed to eager load titulos")
	}

	var resultSlice []*Titulo
	if err = queries.Bind(results, &resultSlice); err != nil {
		return errors.Wrap(err, "failed to bind eager loaded slice titulos")
	}

	if err = results.Close(); err != nil {
		return errors.Wrap(err, "failed to close results in eager load on titulos")
	}
	if err = results.Err(); err != nil {
		return errors.Wrap(err, "error occurred during iteration of eager loaded relations for titulos")
	}

	if len(tituloAfterSelectHooks) != 0 {
		for _, obj := range resultSlice {
			if err := obj.doAfterSelectHooks(ctx, e); err != nil {
				return err
			}
		}
	}
	if singular {
		object.R.PorTitulos = resultSlice
		for _, foreign := range resultSlice {
			if foreign.R == nil {
				foreign.R = &tituloR{}
			}
			foreign.R.Por = object
		}
		return nil
	}

	for _, foreign := range resultSlice {
		for _, local := range slice {
			if local.PorID == foreign.PorID {
				local.R.PorTitulos = append(local.R.PorTitulos, foreign)
				if foreign.R == nil {
					foreign.R = &tituloR{}
				}
				foreign.R.Por = local
				break
			}
		}
	}

	return nil
}

