// RemoveCVB relationship.
// Sets o.R.CVB to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Portador) RemoveCVB(ctx context.Context, exec boil.ContextExecutor, related *ConvenioBancario) error {
	var err error

	queries.SetScanner(&o.CVBID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("cvb_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.CVB = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.CVBPortadors {
		if queries.Equal(o.CVBID, ri.CVBID) {
			continue
		}

		ln := len(related.R.CVBPortadors)
		if ln > 1 && i < ln-1 {
			related.R.CVBPortadors[i] = related.R.CVBPortadors[ln-1]
		}
		related.R.CVBPortadors = related.R.CVBPortadors[:ln-1]
		break
	}
	return nil
}

